import{_ as s,l,o as e,c as o,v as r,p,x as t,d as n,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"B+ 树索引","description":"","frontmatter":{"title":"B+ 树索引","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/bplus-index.md","filePath":"cs/bplus-index.md","lastUpdated":1789023840000}'),h={name:"cs/bplus-index.md"};function B(E,a,u,_,m,A){const i=l("Mermaid");return e(),o("div",null,[a[1]||(a[1]=r('<h1 id="b-树索引" tabindex="-1">B+ 树索引 <a class="header-anchor" href="#b-树索引" aria-label="Permalink to &quot;B+ 树索引&quot;">​</a></h1><div class="epigraph"><p>内节点只指路，叶节点拉成有序链表；等值与范围都从同一棵矮树走。</p><footer>—— 据 Comer, The Ubiquitous B-Tree, CSUR 1979；对照[B 树与外存](/cs/btree-external)</footer></div><p><a href="/cs/heap-cluster">上一课</a>区分了堆与聚簇。本课不重讲空闲空间图。<a href="/cs/heap-cluster">B 树与外存</a>已经给出多路平衡查找树为何适合分页。缺口是：数据库里实际用的是 <strong>B+ 树</strong>——数据（或 rid）只在叶上，内节点是分隔键，叶用兄弟指针支持范围扫描。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>数据结构课的 B 树允许内节点也存记录。库的二级索引要稳定、要扫一段键、要尽量少改内节点。缺口不是再证对数高度，而是约定：查找从根到叶，范围沿叶链走，插入分裂仍保持平衡。聚簇索引可以让叶即数据页；非聚簇叶只存键与 rid，再回<a href="/cs/heap-cluster">堆</a>。</p><p><span class="marginnote">扇出由页大小与键长决定。前缀压缩、后缀截断提高扇出，本课承认它们是页内技巧，不改变树的形状不变量。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>查找：内节点二分选子页，直到叶。等值命中后沿叶链收集重复键（非唯一索引）。插入在叶；满则分裂，中键上推，可能级联到根（长高一层）。删除可合并或与兄弟借键，实践中常惰性标删，以免频繁合并。本课不把并发锁耦合（蟹行、右链）写完，那是后课锁与 MVCC 的交界。</p>',8)),(e(),p(c,null,{default:t(()=>[d(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20ROOT%5B%22%E5%86%85%E8%8A%82%E7%82%B9%3A%20%E5%88%86%E9%9A%94%E9%94%AE%22%5D%20--%3E%20LEAF%5B%22%E5%8F%B6%3A%20%E9%94%AE%20%2B%20rid%20%E6%88%96%E6%95%B0%E6%8D%AE%22%5D%0A%20%20LEAF%20--%3E%20CHAIN%5B%22%E5%8F%B6%E9%93%BE%3A%20%E8%8C%83%E5%9B%B4%22%5D%0A%20%20CHAIN%20--%3E%20HASH%5B%22%E5%90%8E%E8%AF%BE%3A%20%E5%93%88%E5%B8%8C%E7%B4%A2%E5%BC%95%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>B+ 使范围与排序扫描成为一等公民：<code>ORDER BY</code> 与归并连接可以直接吃叶序。覆盖索引若叶上列够用，可免回表。高度通常二三层，缓冲池常把根与上层钉住，点查接近一两次 I/O。这与<a href="/cs/cost-estimate">代价估计</a>里的索引高度项对齐。</p><p>主键约束常靠唯一 B+ 实现：插入前在叶上探测。这是完整性的物理手段，含义仍在<a href="/cs/keys-integrity">键与完整性</a>。</p><p>内节点不存 rid，分裂时上推的是分隔键。这使叶链扫描不必回到根。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 LSM、跳表、GiST 请进主干。也不讲倒排、全文。哈希下一课才对照：等值快、范围弱。并发下的结构修改（SMOs）与 WAL 日志必须原子出现，细节在恢复课。</p><p>复合键与包含列（covering）只改变叶上存什么，不改变「内节点指路、叶上有序」这一条。后课默认：说到二级索引，默认 B+；等值点查也可以走哈希，范围仍走 B+。</p><p>B+ 的矮来自页级扇出，不是来自内存 BST 的旋转。外存课已经讲过多路；本课只钉叶链与回表。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><p>覆盖索引免回表，叶上必须带齐查询需要的列，这是空间换 I/O。</p></li><li><p>唯一约束常落在 B+ 叶探测上，含义仍在键课。</p></li><li><p>堆/聚簇已在；本课把 B 树特化成叶链表的 B+ 索引。</p></li><li><p>等值走根到叶，范围走叶链；回表与否则看聚簇。</p></li><li><p>等值专用的哈希索引是后课对照。</p></li><li><p>出处：Comer, 1979；Ramakrishnan and Gehrke；对照 Knuth 外存查找。</p></li></ul>',10))])}const T=s(h,[["render",B]]);export{b as __pageData,T as default};
